package com.smartlibrary.benchmark;import com.smartlibrary.algorithms.string.*;import java.util.*;
public final class AlgorithmBenchmark {private AlgorithmBenchmark(){}public static void run(String text,String pattern){long t=System.nanoTime();var k=KMP.search(text,pattern);long kt=System.nanoTime()-t;t=System.nanoTime();var z=ZFunction.search(text,pattern);long zt=System.nanoTime()-t;t=System.nanoTime();var r=RabinKarp.search(text,pattern);long rt=System.nanoTime()-t;System.out.printf("%-18s %8d ns %8d comparisons %s%n","KMP",kt,k.comparisons(),k.positions().equals(z.positions()));System.out.printf("%-18s %8d ns %8d comparisons %s%n","Z-function",zt,z.comparisons(),k.positions().equals(z.positions()));System.out.printf("%-18s %8d ns %8d hash checks %s%n","Rabin-Karp",rt,r.hashChecks(),k.positions().equals(r.positions()));}}
